CREATE DATABASE CustomerShoppingDB;

USE CustomerShoppingDB;


select * from customer_shopping_behavior_1_cleaned_data;

-- Q1. What is the total revenue generated by male vs. female customers?

select Gender , SUM(`Purchase Amount (USD)`) As total_revenue
from customer_shopping_behavior_1_cleaned_data
group by Gender
ORDER BY total_revenue DESC;


-- Q2. Which customers used a discount but still spent more than the average purchase amount?

SELECT `Customer ID` , `Purchase Amount (USD)`
FROM customer_shopping_behavior_1_cleaned_data
WHERE `Discount Applied` = "Yes"
AND `Purchase Amount (USD)` >
(SELECT AVG(`Purchase Amount (USD)`)
FROM customer_shopping_behavior_1 );


-- Q3. Which are the top 5 products with the highest average review rating?

SELECT `Item Purchased` , AVG(`Review Rating`) AS Avg_Rating
FROM customer_shopping_behavior_1_cleaned_data 
GROUP BY `Item Purchased`
ORDER BY Avg_Rating DESC
LIMIT 5;


-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

SELECT `Shipping Type` , AVG(`Purchase Amount (USD)`) AS Ave_purchase  
FROM customer_shopping_behavior_1_cleaned_data
WHERE `Shipping Type` IN ('Standard','Express')     
GROUP BY `Shipping Type`;


-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

SELECT `Subscription Status` ,
AVG(`Purchase Amount (USD)`) AS Avg_spend,
SUM(`Purchase Amount (USD)`) AS revenue
FROM customer_shopping_behavior_1_cleaned_data 
GROUP BY `Subscription Status`;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

SELECT `Item Purchased` ,
ROUND(100* AVG(`Discount Applied` = 'Yes'), 2) AS discount_percent
FROM customer_shopping_behavior_1_cleaned_data 
GROUP BY `Item Purchased`
ORDER BY discount_percent DESC
LIMIT 5;


-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

SELECT 
	CASE
		WHEN `Previous Purchases` <= 1 THEN 'New'
        WHEN `Previous Purchases` <= 5 THEN 'Returning'
        ELSE 'Loyal'
	END AS segment,
COUNT(*) AS total_customers
FROM customer_shopping_behavior_1_cleaned_data 
GROUP BY segment;


-- Q8. What are the top 3 most purchased products within each category?

WITH ranked AS (
SELECT Category, `Item Purchased`,
COUNT(*) AS total,
ROW_NUMBER() OVER (
PARTITION BY Category ORDER BY COUNT(*) DESC
) AS rn
FROM customer_shopping_behavior_1_cleaned_data
GROUP BY Category, `Item Purchased`
)
SELECT Category, `Item Purchased`, total
FROM ranked
WHERE rn <= 3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?


SELECT
CASE WHEN `Previous Purchases` > 5
THEN 'Repeat Buyer' ELSE 'Other Buyer'
END AS buyer_type,
COUNT(*) AS total_customers,
SUM(`Subscription Status` = 'Yes') AS subscribers,
ROUND(AVG(`Subscription Status` = 'Yes') * 100, 2) AS subscription_percent
FROM customer_shopping_behavior_1_cleaned_data
GROUP BY buyer_type;


-- Q10. What is the revenue contribution of each age group?

SELECT
	CASE
		WHEN Age BETWEEN 18 AND 25 THEN '18-25'
		WHEN Age BETWEEN 26 AND 35 THEN '26-35'
		WHEN Age BETWEEN 36 AND 45 THEN '36-45'
		WHEN Age BETWEEN 46 AND 55 THEN '46-55'
		WHEN Age BETWEEN 56 AND 65 THEN '56-65'
	ELSE '66+'
	END AS age_group,
SUM(`Purchase Amount (USD)`) AS revenue
FROM customer_shopping_behavior_1_cleaned_data
GROUP BY age_group
order by age_group;


